export function SaveButton({
  label = "{{label}}",
  busy = {{busy}},
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  return (
    <>
      <button
        type="button"
        aria-busy={busy}
        disabled={disabled}
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          minWidth: 110,
          padding: "11px 20px",
          borderRadius: radius,
          border: "none",
          background: bg,
          color: "#FAF7F2",
          font: "600 15px/1 system-ui, sans-serif",
          cursor: disabled ? "not-allowed" : "pointer",
          opacity: disabled ? 0.5 : 1,
        }}
      >
        {busy && (
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="save-spin" aria-hidden="true">
            <circle cx="12" cy="12" r="9" strokeOpacity=".25" />
            <path d="M21 12a9 9 0 00-9-9" />
          </svg>
        )}
        {busy ? "Saving" : label}
      </button>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .save-spin { animation: save-spin .8s linear infinite; }
          @keyframes save-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </>
  );
}
